/**
 * Dynamic highlights cover a 25-block near-view region. A torch can influence
 * another 21 blocks beyond that region, so the bounded source query must reach
 * The query includes the maximum accent radius plus an approach margin so a
 * source is assigned before the camera crosses its influence sphere. This
 * remains constant regardless of render distance.
 */
export const ENVIRONMENT_LIGHT_QUERY_RADIUS = 30;
// Hearthroads trims the already-reduced night pressure by another 40% while
// keeping encounters meaningful near genuine darkness.
export const HOSTILE_SPAWN_ATTEMPT_SCALE = 2.5;
export const PASSIVE_SPAWN_INTERVAL_SECONDS = Object.freeze([1.8, 3.2] as const);
export const HOSTILE_CAP_SCALE = 0.42;

const clamp = (value: number, min: number, max: number) => Math.max(min, Math.min(max, value));

export const POINTER_LOCK_REACQUIRE_SUPPRESSION_EVENTS = 2;
export const POINTER_LOOK_STALE_AFTER_MS = 150;
/** Twelve degrees per presented frame still permits a 720-degree/second turn at 60 FPS. */
export const POINTER_LOOK_MAX_RADIANS_PER_FRAME = Math.PI / 15;

export function gatePointerLockMovement(
  movementX: number,
  movementY: number,
  suppressedEvents: number,
  timing: Readonly<{ eventAgeMs?: number; frameAgeMs?: number }> = {},
): Readonly<{ apply: boolean; remainingSuppressedEvents: number; reason: "accepted" | "empty" | "invalid" | "reacquire" | "stale" }> {
  const remainingSuppressedEvents = Math.max(0, Math.trunc(Number(suppressedEvents) || 0));
  if (!Number.isFinite(movementX) || !Number.isFinite(movementY)) {
    return { apply: false, remainingSuppressedEvents, reason: "invalid" };
  }
  if (remainingSuppressedEvents > 0) {
    return { apply: false, remainingSuppressedEvents: remainingSuppressedEvents - 1, reason: "reacquire" };
  }
  const eventAgeMs = Math.max(0, Number(timing.eventAgeMs) || 0);
  const frameAgeMs = Math.max(0, Number(timing.frameAgeMs) || 0);
  if (eventAgeMs > POINTER_LOOK_STALE_AFTER_MS || frameAgeMs > POINTER_LOOK_STALE_AFTER_MS) {
    return { apply: false, remainingSuppressedEvents: 0, reason: "stale" };
  }
  const apply = movementX !== 0 || movementY !== 0;
  return { apply, remainingSuppressedEvents: 0, reason: apply ? "accepted" : "empty" };
}

/**
 * Limits the net view rotation that can become visible in one rendered frame.
 * Excess pointer/touch motion is intentionally dropped rather than replayed as
 * a delayed camera glide after a hitch.
 */
export function boundLookDeltaForFrame(
  movementX: number,
  movementY: number,
  sensitivity: number,
  appliedX = 0,
  appliedY = 0,
  maximumRadians = POINTER_LOOK_MAX_RADIANS_PER_FRAME,
) {
  const safeSensitivity = clamp(Math.abs(Number(sensitivity) || 0.0022), 0.0001, 0.02);
  const pixelLimit = Math.max(1, Math.abs(Number(maximumRadians) || POINTER_LOOK_MAX_RADIANS_PER_FRAME) / safeSensitivity);
  const currentX = Number.isFinite(appliedX) ? appliedX : 0;
  const currentY = Number.isFinite(appliedY) ? appliedY : 0;
  const requestedX = currentX + (Number.isFinite(movementX) ? movementX : 0);
  const requestedY = currentY + (Number.isFinite(movementY) ? movementY : 0);
  const requestedLength = Math.hypot(requestedX, requestedY);
  const scale = requestedLength > pixelLimit ? pixelLimit / requestedLength : 1;
  const totalX = requestedX * scale;
  const totalY = requestedY * scale;
  return {
    deltaX: totalX - currentX,
    deltaY: totalY - currentY,
    totalX,
    totalY,
    clamped: scale < 1,
  } as const;
}

/** Multiplicative movement effects shared by walking, sprinting and swimming. */
export function timedMovementMultiplier(buffs: Readonly<Record<string, number>> | undefined, nowSeconds: number) {
  const peppermintRush = (buffs?.["peppermint-rush"] ?? 0) > nowSeconds ? 1.24 : 1;
  const moonstep = (buffs?.moonstep ?? 0) > nowSeconds ? 1.16 : 1;
  const dragonSlow = (buffs?.["dragon-slowed"] ?? 0) > nowSeconds ? 0.56 : 1;
  return peppermintRush * moonstep * dragonSlow;
}

function environmentLightDistance(type: BlockId) {
  if ([BlockId.LuminousRoot, BlockId.GlowmossCarpet, BlockId.LuminousAlgae, BlockId.LivingVein].includes(type)) return 8;
  if ([BlockId.LuminousGills, BlockId.LanternBloom, BlockId.ResonantCrystal, BlockId.CrystalCluster, BlockId.FumaroleVent, BlockId.VeinmetalHeart].includes(type)) return 11;
  return type === BlockId.Lava ? 18 : type === BlockId.Furnace ? 8 : type === BlockId.RuneStone ? 8 : type === BlockId.LightningBugJar ? 10 : isTorchBlock(type) ? 21 : 15;
}

function isEnvironmentLightBlock(type: BlockId) {
  return isTorchBlock(type) || type === BlockId.Lava || type === BlockId.Glowstone || type === BlockId.CrystalBlock || type === BlockId.RuneStone
    || type === BlockId.Dreamblossom || type === BlockId.GiantDreamblossom || type === BlockId.LightningBugJar
    || [BlockId.LuminousRoot, BlockId.StarbloomCap, BlockId.LuminousGills, BlockId.LanternBloom, BlockId.GlowmossCarpet,
      BlockId.LuminousAlgae, BlockId.ResonantCrystal, BlockId.CrystalCluster, BlockId.FumaroleVent,
      BlockId.LivingVein, BlockId.VeinmetalHeart, BlockId.CaveMarker].includes(type);
}

function setEnvironmentLightPosition(target: THREE.Vector3, source: Pick<EnvironmentLightSource, "x" | "y" | "z" | "type">) {
  target.set(source.x, source.y, source.z);
  if (!isTorchBlock(source.type)) return target;
  target.y += 0.35;
  if (source.type === BlockId.TorchWallNorth) target.z -= 0.2;
  else if (source.type === BlockId.TorchWallSouth) target.z += 0.2;
  else if (source.type === BlockId.TorchWallEast) target.x += 0.2;
  else if (source.type === BlockId.TorchWallWest) target.x -= 0.2;
  return target;
}

export function torchBlockForPlacement(target: Pick<VoxelHit, "x" | "y" | "z" | "placeX" | "placeY" | "placeZ">, replacingTarget = false) {
  if (replacingTarget || target.placeY > target.y) return BlockId.Torch;
  if (target.placeY < target.y) return null;
  if (target.placeX > target.x) return BlockId.TorchWallEast;
  if (target.placeX < target.x) return BlockId.TorchWallWest;
  if (target.placeZ > target.z) return BlockId.TorchWallSouth;
  if (target.placeZ < target.z) return BlockId.TorchWallNorth;
  return BlockId.Torch;
}

export type TorchInteractionBounds = Readonly<{ minX: number; minY: number; minZ: number; maxX: number; maxY: number; maxZ: number }>;

/** Narrow selection bounds follow the authored floor/wall torch silhouette. */
export function torchInteractionBounds(type: BlockId, x: number, y: number, z: number): TorchInteractionBounds | null {
  if (type === BlockId.Torch) return { minX: x - 0.17, minY: y - 0.5, minZ: z - 0.17, maxX: x + 0.17, maxY: y + 0.5, maxZ: z + 0.17 };
  if (type === BlockId.TorchWallNorth) return { minX: x - 0.22, minY: y - 0.36, minZ: z + 0.04, maxX: x + 0.22, maxY: y + 0.5, maxZ: z + 0.5 };
  if (type === BlockId.TorchWallSouth) return { minX: x - 0.22, minY: y - 0.36, minZ: z - 0.5, maxX: x + 0.22, maxY: y + 0.5, maxZ: z - 0.04 };
  if (type === BlockId.TorchWallEast) return { minX: x - 0.5, minY: y - 0.36, minZ: z - 0.22, maxX: x - 0.04, maxY: y + 0.5, maxZ: z + 0.22 };
  if (type === BlockId.TorchWallWest) return { minX: x + 0.04, minY: y - 0.36, minZ: z - 0.22, maxX: x + 0.5, maxY: y + 0.5, maxZ: z + 0.22 };
  return null;
}

export function rayDistanceToTorchBounds(
  origin: Readonly<{ x: number; y: number; z: number }>,
  direction: Readonly<{ x: number; y: number; z: number }>,
  bounds: TorchInteractionBounds,
  maximumDistance: number,
) {
  let entry = 0;
  let exit = maximumDistance;
  const axes = [
    [origin.x, direction.x, bounds.minX, bounds.maxX],
    [origin.y, direction.y, bounds.minY, bounds.maxY],
    [origin.z, direction.z, bounds.minZ, bounds.maxZ],
  ] as const;
  for (const [coordinate, component, minimum, maximum] of axes) {
    if (Math.abs(component) < 1e-8) {
      if (coordinate < minimum || coordinate > maximum) return null;
      continue;
    }
    const first = (minimum - coordinate) / component;
    const second = (maximum - coordinate) / component;
    entry = Math.max(entry, Math.min(first, second));
    exit = Math.min(exit, Math.max(first, second));
    if (exit < entry) return null;
  }
  return entry <= maximumDistance ? entry : null;
}

export type BedPlacement = { foot: BlockId; head: BlockId; dx: number; dz: number };

export function bedPlacementForYaw(yaw: number): BedPlacement {
  const forwardX = -Math.sin(yaw);
  const forwardZ = -Math.cos(yaw);
  if (Math.abs(forwardX) > Math.abs(forwardZ)) {
    return forwardX >= 0
      ? { foot: BlockId.BedEastFoot, head: BlockId.BedEastHead, dx: 1, dz: 0 }
      : { foot: BlockId.BedWestFoot, head: BlockId.BedWestHead, dx: -1, dz: 0 };
  }
  return forwardZ >= 0
    ? { foot: BlockId.BedSouthFoot, head: BlockId.BedSouthHead, dx: 0, dz: 1 }
    : { foot: BlockId.BedNorthFoot, head: BlockId.BedNorthHead, dx: 0, dz: -1 };
}

export function bedCounterpart(type: BlockId, x: number, y: number, z: number) {
  switch (type) {
    case BlockId.BedNorthFoot: return { x, y, z: z - 1, type: BlockId.BedNorthHead };
    case BlockId.BedNorthHead: return { x, y, z: z + 1, type: BlockId.BedNorthFoot };
    case BlockId.BedSouthFoot: return { x, y, z: z + 1, type: BlockId.BedSouthHead };
    case BlockId.BedSouthHead: return { x, y, z: z - 1, type: BlockId.BedSouthFoot };
    case BlockId.BedEastFoot: return { x: x + 1, y, z, type: BlockId.BedEastHead };
    case BlockId.BedEastHead: return { x: x - 1, y, z, type: BlockId.BedEastFoot };
    case BlockId.BedWestFoot: return { x: x - 1, y, z, type: BlockId.BedWestHead };
    case BlockId.BedWestHead: return { x: x + 1, y, z, type: BlockId.BedWestFoot };
    default: return null;
  }
}

export function bedRespawnCandidates(type: BlockId, x: number, y: number, z: number) {
  const partner = bedCounterpart(type, x, y, z);
  const bedCells = [{ x, y, z }, ...(partner ? [{ x: partner.x, y: partner.y, z: partner.z }] : [])];
  const seen = new Set<string>();
  const candidates: Array<{ x: number; y: number; z: number }> = [];
  for (const bed of bedCells) for (const [dx, dz] of [[0, 1], [1, 0], [0, -1], [-1, 0]] as const) {
    const candidate = { x: bed.x + dx, y: bed.y, z: bed.z + dz };
    const key = `${candidate.x},${candidate.y},${candidate.z}`;
    if (bedCells.some((cell) => cell.x === candidate.x && cell.z === candidate.z) || seen.has(key)) continue;
    seen.add(key);
    candidates.push(candidate);
  }
  return candidates;
}

export function isInstantBreakBlock(type: BlockId) {
  return ["cross", "bush", "fruit", "aquatic", "tall-flower"].includes(BLOCKS[type]?.shape ?? "");
}

export function shouldShowIncorrectToolFeedback(harvested: boolean) {
  return !harvested;
}

export function isOpenableBlock(type: BlockId) {
  return [
    BlockId.DoorClosedLower, BlockId.DoorClosedUpper, BlockId.DoorOpenLower, BlockId.DoorOpenUpper,
    BlockId.DoorXClosedLower, BlockId.DoorXClosedUpper, BlockId.DoorXOpenLower, BlockId.DoorXOpenUpper,
    BlockId.FenceGateNorthSouthClosed, BlockId.FenceGateNorthSouthOpen, BlockId.FenceGateEastWestClosed, BlockId.FenceGateEastWestOpen,
    BlockId.CraftingTable, BlockId.Furnace, BlockId.Chest, BlockId.ButterflyExhibit,
    BlockId.Apiary, BlockId.WildBeehive, BlockId.CaptureOrbRack, BlockId.CreatureHealer,
    BlockId.CartographyTable, BlockId.AlchemyStand, BlockId.Wayshrine, BlockId.Distillery, BlockId.HearthChair,
    BlockId.BedNorthFoot, BlockId.BedNorthHead, BlockId.BedSouthFoot, BlockId.BedSouthHead,
    BlockId.BedEastFoot, BlockId.BedEastHead, BlockId.BedWestFoot, BlockId.BedWestHead,
  ].includes(type) || isDoorBlock(type);
}

export function shouldBypassOpenableUse(crouching: boolean, heldPlacesBlock: boolean, target: BlockId) {
  return crouching && heldPlacesBlock && isOpenableBlock(target);
}

export function mobPopulationCaps(totalCap: number) {
  const total = Math.max(0, Math.floor(totalCap));
  const passive = Math.ceil(total * 0.68);
  return { total, passive, hostile: total === 0 ? 0 : Math.max(1, Math.floor((total - passive) * HOSTILE_CAP_SCALE)) };
}

export type NaturalMobPopulationEntry = Readonly<{
  hostile: boolean;
  persistentPoiResident?: boolean;
}>;

/**
 * Settlement and authored POI residents have their own population contracts.
 * Keeping them out of the roaming wildlife budget prevents one visited town
 * from permanently suppressing every later natural spawn.
 */
export function naturalMobPopulation(mobs: readonly NaturalMobPopulationEntry[]) {
  let passive = 0;
  let hostile = 0;
  for (const mob of mobs) {
    if (mob.persistentPoiResident) continue;
    if (mob.hostile) hostile += 1;
    else passive += 1;
  }
  return { total: passive + hostile, passive, hostile };
}

export type SimulationInterestPoint = Readonly<{ id: string; x: number; y: number; z: number; yaw: number }>;

type NaturalAquaticSpawnCandidate = Readonly<{
  x: number;
  z: number;
  distance: number;
  habitat: FishHabitat;
  column: AquaticSpawnColumn;
  underground: boolean;
}>;

/** One shared spawn clock, with a bounded sublinear cap for separated players. */
export function multiplayerNaturalMobCap(baseCap: number, playerCount: number) {
  const players = Math.max(1, Math.min(4, Math.floor(playerCount)));
  return Math.max(0, Math.floor(Math.max(0, baseCap) * Math.sqrt(players)));
}

/** Round-robin interests keep one distant guest from losing every spawn roll. */
export function selectSimulationInterest(points: readonly SimulationInterestPoint[], cursor: number) {
  if (!points.length) return null;
  return points[Math.abs(Math.trunc(cursor)) % points.length];
}

export function nearestSimulationInterest(points: readonly SimulationInterestPoint[], x: number, z: number) {
  let nearest: SimulationInterestPoint | null = null;
  let distanceSquared = Infinity;
  for (const point of points) {
    const candidate = (point.x - x) ** 2 + (point.z - z) ** 2;
    if (candidate >= distanceSquared) continue;
    nearest = point;
    distanceSquared = candidate;
  }
  return nearest ? { point: nearest, distanceSquared } : null;
}

export function positionInPlayerViewCone(yaw: number, dx: number, dz: number, halfAngle = Math.PI * 0.34) {
  const distance = Math.hypot(dx, dz);
  if (distance < 0.0001) return true;
  const forwardX = -Math.sin(yaw);
  const forwardZ = -Math.cos(yaw);
  return (dx * forwardX + dz * forwardZ) / distance >= Math.cos(halfAngle);
}

const LEVIATHAN_KINDS = new Set<MobKind>(["worldshell-leviathan", "aetherbell-larva", "aetherbell-leviathan"]);
const DRAGON_KINDS = new Set<MobKind>(["fire-dragon", "ice-dragon", "steel-dragon", "sea-dragon", "gold-dragon", "silver-dragon"]);
const ARCHIVE_SHELF_BLOCK_SET = new Set<BlockId>(ARCHIVE_SHELF_BLOCKS);
const DRACONIC_PLAYER_GEAR = new Set<ItemCode>([
  Item.DragonboneGreatsword, Item.DragonbonePickaxe, Item.DragonboneAxe,
  Item.FireScaleHelm, Item.FireScalePlate, Item.FireScaleGreaves, Item.FireScaleBoots,
  Item.IceScaleHelm, Item.IceScalePlate, Item.IceScaleGreaves, Item.IceScaleBoots,
  Item.SteelScaleHelm, Item.SteelScalePlate, Item.SteelScaleGreaves, Item.SteelScaleBoots,
]);
const DRAGON_SCALE_ITEMS = new Set<ItemCode>([Item.FireDragonScale, Item.IceDragonScale, Item.SteelDragonScale, Item.SeaDragonScale, Item.GoldDragonScale, Item.SilverDragonScale]);
/** Species whose first successful capture advances A Living Archive. */
const DRAGONWAKE_RARE_CAPTURE_KINDS = new Set<MobKind>([
  "bloom-monarch", "fen-lantern", "mistmane", "sakurakit", "tidepup",
  "worldshell-leviathan", "aetherbell-leviathan", "reliquary-sentinel",
  "fire-dragon", "ice-dragon", "steel-dragon", "sea-dragon", "gold-dragon", "silver-dragon",
]);

function isLeviathanKind(kind: MobKind): kind is "worldshell-leviathan" | "aetherbell-larva" | "aetherbell-leviathan" {
  return LEVIATHAN_KINDS.has(kind);
}

function isDragonKind(kind: MobKind): kind is DragonKind {
  return DRAGON_KINDS.has(kind);
}

function dragonTypeForKind(kind: DragonKind): DragonType {
  return kind.slice(0, kind.indexOf("-")) as DragonType;
}

function dragonFoodForItem(item: ItemCode): DragonFood | null {
  if (item === Item.RawDragonMeat || item === Item.RottenFlesh) return "raw-meat";
  if (item === Item.CookedDragonMeat) return "cooked-meat";
  if (item === Item.RawFish || item === Item.CookedFish) return "fish";
  return null;
}

function dragonScaleItem(type: DragonType) {
  return type === "fire" ? Item.FireDragonScale : type === "ice" ? Item.IceDragonScale : type === "sea" ? Item.SeaDragonScale : type === "gold" ? Item.GoldDragonScale : type === "silver" ? Item.SilverDragonScale : Item.SteelDragonScale;
}

function dragonEggItem(type: DragonType) {
  return type === "fire" ? Item.FireDragonEgg : type === "ice" ? Item.IceDragonEgg : type === "sea" ? Item.SeaDragonEgg : type === "gold" ? Item.GoldDragonEgg : type === "silver" ? Item.SilverDragonEgg : Item.SteelDragonEgg;
}

/** Central ore-yield contract shared by runtime harvesting and deterministic tests. */
export function oreBlockDropRange(type: BlockId): readonly [item: ItemCode, minimum: number, maximum: number] | null {
  if (type === BlockId.IronOre) return [Item.RawIron, 1, 4];
  if (type === BlockId.CopperOre) return [Item.RawCopper, 1, 4];
  return null;
}

function dragonLootItemCode(item: string): ItemCode | null {
  const byName: Readonly<Record<string, ItemCode>> = {
    RawDragonMeat: Item.RawDragonMeat,
    DragonBone: Item.DragonBone,
    FireDragonScale: Item.FireDragonScale,
    IceDragonScale: Item.IceDragonScale,
    SteelDragonScale: Item.SteelDragonScale,
    SeaDragonScale: Item.SeaDragonScale,
    GoldDragonScale: Item.GoldDragonScale,
    SilverDragonScale: Item.SilverDragonScale,
    FireDragonHeart: Item.FireDragonHeart,
    IceDragonHeart: Item.IceDragonHeart,
    SteelDragonHeart: Item.SteelDragonHeart,
    SeaDragonHeart: Item.SeaDragonHeart,
    GoldDragonHeart: Item.GoldDragonHeart,
    SilverDragonHeart: Item.SilverDragonHeart,
    FireDragonSkull: Item.FireDragonSkull,
    IceDragonSkull: Item.IceDragonSkull,
    SteelDragonSkull: Item.SteelDragonSkull,
    SeaDragonSkull: Item.SeaDragonSkull,
    GoldDragonSkull: Item.GoldDragonSkull,
    SilverDragonSkull: Item.SilverDragonSkull,
    FireDragonEgg: Item.FireDragonEgg,
    IceDragonEgg: Item.IceDragonEgg,
    SteelDragonEgg: Item.SteelDragonEgg,
    SeaDragonEgg: Item.SeaDragonEgg,
    GoldDragonEgg: Item.GoldDragonEgg,
    SilverDragonEgg: Item.SilverDragonEgg,
  };
  return byName[item] ?? null;
}

function dragonCatalystType(item: ItemCode): DragonType | null {
  if (item === Item.FireBreedingCatalyst) return "fire";
  if (item === Item.IceBreedingCatalyst) return "ice";
  if (item === Item.SteelBreedingCatalyst) return "steel";
  if (item === Item.StarCoralShard) return "sea";
  if (item === Item.GoldBreedingCatalyst) return "gold";
  if (item === Item.SilverBreedingCatalyst) return "silver";
  return null;
}

function titleCaseDragon(type: DragonType) {
  return `${type[0].toUpperCase()}${type.slice(1)}`;
}

function worldTicksForDragonDelta(seconds: number, dayLengthMinutes: number) {
  return Math.max(0, Math.round(seconds / Math.max(60, dayLengthMinutes * 60) * 24_000));
}

/** Persistent age provides a deterministic per-dragon level without save churn. */
function dragonLevelForState(state: DragonState) {
  return clamp(Math.floor(state.ageTicks / 24_000 * 2) + state.stage * 3, 1, 1_000);
}

function createWildLeviathanGrowth(kind: "worldshell-leviathan" | "aetherbell-larva" | "aetherbell-leviathan", id: number): LeviathanGrowthState {
  const species: LeviathanSpecies = kind === "worldshell-leviathan" ? "worldshell-leviathan" : "aetherbell-leviathan";
  const adult = kind !== "aetherbell-larva";
  const ageTicks = adult ? LEVIATHAN_LIFECYCLE_CONTRACT.adultAtTicks : 0;
  return {
    schemaVersion: 1,
    creatureId: `${species}:wild:${id}`,
    sourceEggId: `wild:${id}`,
    species,
    kind,
    geneticSeed: Math.imul(id, 0x9e3779b1) >>> 0,
    ageTicks,
    stage: adult ? "adult" : "tiny",
    growthScale: adult ? 1 : 0.08,
    aquaticOnly: !adult,
    customName: null,
    tamed: false,
    ownerId: null,
    saddled: false,
    chestModules: 0,
  };
}

function placedLeviathanEggMetadata(metadata: Record<string, unknown> | undefined): LeviathanEggMetadata | null {
  if (metadata?.kind !== "placed-leviathan-egg" || !metadata.egg || typeof metadata.egg !== "object") return null;
  const egg = metadata.egg as Partial<LeviathanEggMetadata>;
  if (egg.schemaVersion !== 1 || typeof egg.eggId !== "string"
    || (egg.species !== "worldshell-leviathan" && egg.species !== "aetherbell-leviathan")
    || typeof egg.geneticSeed !== "number" || typeof egg.incubationTicks !== "number" || typeof egg.submergedTicks !== "number") return null;
  return egg as LeviathanEggMetadata;
}

export function placedDragonEggMetadata(metadata: Record<string, unknown> | undefined, requirePlaced = true): DragonEgg | null {
  if (!metadata || (requirePlaced ? metadata.kind !== "placed-dragon-egg" : metadata.kind !== "placed-dragon-egg" && metadata.kind !== "dragon-egg")) return null;
  if (!metadata.egg || typeof metadata.egg !== "object") return null;
  return dragonEggFromDropMetadata({ kind: "dragon-egg", egg: metadata.egg });
}

function dragonSpawnEggMetadata(metadata: Record<string, unknown> | undefined): DragonSpawnEgg | null {
  if (metadata?.kind !== "dragon-spawn-egg" || !metadata.spawnEgg || typeof metadata.spawnEgg !== "object") return null;
  const value = metadata.spawnEgg as Partial<DragonSpawnEgg>;
  const schemaVersion = (value as { schemaVersion?: number }).schemaVersion;
  if ((schemaVersion !== 1 && schemaVersion !== DRAGON_SCHEMA_VERSION) || value.kind !== "ready-dragon-spawn-egg" || typeof value.preparedAtTick !== "number" || !value.egg) return null;
  const egg = placedDragonEggMetadata({ kind: "dragon-egg", egg: value.egg as unknown as Record<string, unknown> }, false);
  return egg ? { schemaVersion: DRAGON_SCHEMA_VERSION, kind: "ready-dragon-spawn-egg", preparedAtTick: value.preparedAtTick, egg } : null;
}

export function nextPeelopBananaShedSeconds(id: number, cycle: number) {
  const mixed = Math.imul((id | 0) ^ Math.imul(cycle | 0, 0x45d9f3b), 0x27d4eb2d) >>> 0;
  return 135 + (mixed % 76);
}

export function combatSceneForEncounter(encounter: number): "combatA" | "combatB" {
  return Math.abs(Math.floor(encounter)) % 2 === 0 ? "combatA" : "combatB";
}

export function nextSleepTransition(worldTime: number, day: number, target: SleepTarget) {
  const targetTime = target === "morning" ? 0.27 : 0.77;
  const normalized = ((Number(worldTime) || 0) % 1 + 1) % 1;
  const nextDay = day + (normalized + 0.0001 >= targetTime ? 1 : 0);
  return { worldTime: targetTime, day: Math.max(1, Math.floor(nextDay)) };
}

/**
 * Scores a world-space light source using stable, nearest-first budgeting.
 * Local illumination must not disappear merely because the camera turns away
 * from its source: a torch behind the player can still light the room they are
 * looking into. Source type and existing-slot hysteresis are only tie-breakers.
 */
export function environmentLightPriority(
  source: Pick<EnvironmentLightSource, "x" | "y" | "z" | "type">,
  cameraPosition: Pick<THREE.Vector3, "x" | "y" | "z">,
  _cameraForward: Pick<THREE.Vector3, "x" | "y" | "z">,
  previouslyAssigned = false,
) {
  const dx = source.x - cameraPosition.x;
  const dy = source.y - cameraPosition.y;
  const dz = source.z - cameraPosition.z;
  const distanceSquared = dx * dx + dy * dy + dz * dz;
  const sourceBias = source.type === BlockId.CrystalBlock ? -1.25 : source.type === BlockId.Glowstone ? -0.7 : 0;
  return distanceSquared + sourceBias - (previouslyAssigned ? 25 : 0);
}

/** Bounded dynamic-resolution governor; chunk distance and simulation stay intact. */
export function nextAdaptivePixelRatio(current: number, nativeMaximum: number, averageFrameMs: number, touchMode: boolean) {
  const minimum = Math.min(nativeMaximum, touchMode ? 0.72 : 0.82);
  const resolved = averageFrameMs > 22.5
    ? clamp(current - 0.1, minimum, nativeMaximum)
    : averageFrameMs < 15.2
      ? clamp(current + 0.05, minimum, nativeMaximum)
      : clamp(current, minimum, nativeMaximum);
  return Math.round(resolved * 100) / 100;
}

export function isDoubleForwardTap(previousTap: number, currentTap: number, windowMilliseconds = 310) {
  const elapsed = currentTap - previousTap;
  return Number.isFinite(elapsed) && elapsed >= 45 && elapsed <= windowMilliseconds;
}

export function resolveCreativeFlightTap(
  flying: boolean,
  previousTap: number,
  currentTap: number,
  windowMilliseconds = CREATIVE_FLIGHT_TOGGLE_WINDOW_MS,
) {
  const elapsed = currentTap - previousTap;
  const toggled = Number.isFinite(elapsed) && elapsed >= 45 && elapsed <= windowMilliseconds;
  return {
    flying: toggled ? !flying : flying,
    previousTap: toggled ? -Infinity : currentTap,
    toggled,
  } as const;
}

export type UndergroundAmbientCuePlan = Readonly<{ sample: SampleKind; gain: number; playbackRate: number }>;

/** Sparse habitat one-shots sit over the shared quiet cave bed. */
export function undergroundAmbientCue(biome: UndergroundBiomeId): UndergroundAmbientCuePlan | null {
  if (biome === UndergroundBiomeId.RootweaveGrotto) return { sample: "copperMoleSniff", gain: 0.18, playbackRate: 0.72 };
  if (biome === UndergroundBiomeId.StarbloomHollows) return { sample: "owlCallA", gain: 0.16, playbackRate: 1.35 };
  if (biome === UndergroundBiomeId.GlasswaterDeeps) return { sample: "waterSplash", gain: 0.2, playbackRate: 0.78 };
  if (biome === UndergroundBiomeId.PillarstoneReaches) return { sample: "shadecrawlerStoneChitter", gain: 0.15, playbackRate: 0.66 };
  if (biome === UndergroundBiomeId.CrystaldeepGallery) return { sample: "magicAttack", gain: 0.12, playbackRate: 1.52 };
  if (biome === UndergroundBiomeId.EmberdeepFumaroles) return { sample: "scaryGrumble", gain: 0.14, playbackRate: 1.45 };
  return null;
}

/** A long visible/particle wind-up precedes the short damaging steam pulse. */
export function fumaroleSurgeAt(simulationSeconds: number) {
  const seconds = Number.isFinite(simulationSeconds) ? simulationSeconds : 0;
  const phase = ((seconds % 4.8) + 4.8) % 4.8;
  return { phase, warning: phase >= 3.15, surging: phase < 1.05 } as const;
}

function blockKey(x: number, y: number, z: number) {
  return `${x},${y},${z}`;
}

function blockPositionFromKey(key: string) {
  const [x, y, z] = key.split(",").map(Number);
  return Number.isFinite(x) && Number.isFinite(y) && Number.isFinite(z) ? { x, y, z } : null;
}

export function deepgearLiftDestinationY(
  currentY: number,
  prefer: "up" | "down",
  getBlock: (y: number) => BlockId | undefined,
  minimumY = MIN_Y,
  maximumY = MAX_Y,
) {
  const clearStop = (y: number) => getBlock(y) === BlockId.DeepgearLift
    && !BLOCKS[getBlock(y + 1) ?? BlockId.Bedrock]?.solid
    && !BLOCKS[getBlock(y + 2) ?? BlockId.Bedrock]?.solid;
  const search = (direction: 1 | -1) => {
    for (let y = currentY + direction; y >= minimumY && y <= maximumY; y += direction) if (clearStop(y)) return y;
    return null;
  };
  return prefer === "up" ? search(1) ?? search(-1) : search(-1) ?? search(1);
}

