export function resolveStructureLootItem(itemKey: string): ItemCode | null {
  return STRUCTURE_LOOT_ITEMS[itemKey] ?? null;
}

export function readSavedWorld(): WorldSave | null {
  if (typeof window === "undefined") return null;
  try {
    const storage = new WorldStorage(window.localStorage);
    try {
      const id = storage.activeWorldId;
      if (id) {
        const loaded = storage.loadWorld(id, false);
        if (loaded.ok) return { ...loaded.value.save, options: loaded.value.options };
      }
      const raw = window.localStorage.getItem(SAVE_KEY);
      return raw ? migrateSavedWorld(JSON.parse(raw)) : null;
    } finally {
      storage.dispose();
    }
  } catch {
    return null;
  }
}

export function migrateSavedWorld(value: unknown): WorldSave | null {
  if (!value || typeof value !== "object") return null;
  const parsed = value as WorldSave;
  if (parsed.version !== 2 || typeof parsed.seed !== "string") return null;
  if (parsed.generatorVersion === GENERATOR_VERSION) return {
    ...parsed,
    generatorProfile: parsed.generatorProfile === "legacy-v14" ? "legacy-v14" : "world-below-v15",
  };
  if (parsed.generatorVersion === 17) return {
    ...parsed,
    generatorVersion: GENERATOR_VERSION,
    generatorProfile: parsed.generatorProfile === "legacy-v14" ? "legacy-v14" : "world-below-v15",
  };
  if (parsed.generatorVersion === 16) return {
    ...parsed,
    generatorVersion: GENERATOR_VERSION,
    generatorProfile: parsed.generatorProfile === "legacy-v14" ? "legacy-v14" : "world-below-v15",
    options: { ...parsed.options, settlementPattern: "legacy-scattered-v1" },
  };
  if (parsed.generatorVersion === 15) return {
    ...parsed,
    generatorVersion: GENERATOR_VERSION,
    generatorProfile: parsed.generatorProfile === "legacy-v14" ? "legacy-v14" : "world-below-v15",
    options: { ...parsed.options, settlementPattern: "legacy-scattered-v1" },
  };
  if (parsed.generatorVersion === 3 || parsed.generatorVersion === 4 || parsed.generatorVersion === 5 || parsed.generatorVersion === 6 || parsed.generatorVersion === 7 || parsed.generatorVersion === 8 || parsed.generatorVersion === 9 || parsed.generatorVersion === 10 || parsed.generatorVersion === 11 || parsed.generatorVersion === 12 || parsed.generatorVersion === 13 || parsed.generatorVersion === 14) return { ...parsed, generatorVersion: GENERATOR_VERSION, generatorProfile: "legacy-v14", options: { ...parsed.options, settlementPattern: "legacy-scattered-v1" } };
  if (parsed.generatorVersion !== 2) return null;
  const indexOffset = (LEGACY_GENERATOR_MIN_Y - MIN_Y) * 16 * 16;
  const edits: ChunkEditSave = {};
  for (const [key, entries] of Object.entries(parsed.edits ?? {})) {
    if (!Array.isArray(entries)) continue;
    edits[key] = entries
      .filter((entry): entry is [number, number] => Array.isArray(entry) && Number.isFinite(entry[0]) && Number.isFinite(entry[1]))
      .map(([index, type]) => [Math.trunc(index) + indexOffset, Math.trunc(type)]);
  }
  return { ...parsed, generatorVersion: GENERATOR_VERSION, generatorProfile: "legacy-v14", options: { ...parsed.options, settlementPattern: "legacy-scattered-v1" }, edits };
}

export function restoreChestStorage(saved: Record<string, ChestState> = {}) {
  return new Map(Object.entries(saved).map(([key, value]) => {
    const size = key.startsWith("exhibit:")
      ? clamp(value.length || 1, 1, 20)
      : key.startsWith("boat:")
        ? 18
        : key.startsWith("leviathan:") && key.endsWith(":cargo")
          ? clamp(Math.ceil(Math.max(27, value.length || 27) / 27) * 27, 27, 162)
        : key.includes("|") ? 54 : 27;
    return [key, Array.from({ length: size }, (_, index) => normalizeCaptureOrbInventorySlot(value[index] ?? null))] as const;
  }));
}

/** Converts real simulation seconds into the canonical 24,000-tick world day. */
export function worldTicksForDelta(elapsedSeconds: number, dayLengthMinutes: number) {
  if (!Number.isFinite(elapsedSeconds) || elapsedSeconds <= 0) return 0;
  const daySeconds = Math.max(60, (Number.isFinite(dayLengthMinutes) ? dayLengthMinutes : 20) * 60);
  return elapsedSeconds * LEVIATHAN_LIFECYCLE_CONTRACT.ticksPerDay / daySeconds;
}

export function captureResonanceMatched(statuses: readonly ActiveCombatStatus[] | null | undefined, nowSeconds: number) {
  return (statuses ?? []).some((status) => ["inspired", "hushed", "dazzled"].includes(status.id)
    && status.expiresAtSeconds > nowSeconds);
}

export function aquaticSpawnHeight(kind: MobKind, floorY: number, waterSurfaceY: number, roll = 0.5) {
  if (!Number.isFinite(floorY) || !Number.isFinite(waterSurfaceY) || waterSurfaceY <= floorY) return null;
  const depth = Math.max(0, waterSurfaceY - floorY - 1);
  const unit = clamp(Number.isFinite(roll) ? roll : 0.5, 0, 1);
  if (kind === "abyss-skater") return floorY + 0.7;
  if (kind === "tideglass-crab") return floorY + 0.65;
  if (aquaticSpawnBandForMob(kind) === "floor") return floorY + Math.max(0.58, MOB_DEFS[kind].footOffset);
  if (kind === "worldshell-leviathan") return depth >= 3 ? waterSurfaceY - 0.8 : null;
  if (kind === "aetherbell-leviathan") {
    // The adult's trailing ribbons extend a little over five blocks below its
    // origin, so shallow columns are not valid natural spawn sites.
    return depth >= 6 ? clamp(floorY + 5.4 + unit * Math.max(0, depth - 6.1), floorY + 5.4, waterSurfaceY - 0.6) : null;
  }
  if (kind === "dreadcoil") return floorY + Math.max(1.2, depth * 0.28);
  if (kind === "aetherbell-larva") return floorY + Math.max(1, depth * 0.36);
  return floorY + 0.8 + unit * Math.max(0.2, depth - 1.2);
}

export type AquaticSpawnColumn = Readonly<{
  floorY: number;
  bottomY: number;
  surfaceY: number;
  liquid: "water" | "syrup";
  neighborCells: number;
}>;

const aquaticLiquidMatches = (type: BlockId | undefined, liquid: AquaticSpawnColumn["liquid"]) => liquid === "syrup"
  ? type === BlockId.Syrup
  : blockContainsWater(type);

/**
 * Finds a real contiguous liquid segment without asking the dry-land floor
 * resolver to treat water as walkable air. The small horizontal-volume check
 * prevents a bucket cell or one-wide decorative trickle from growing wildlife.
 */
export function findAquaticSpawnColumn(
  world: Pick<ChunkWorld, "getBlock">,
  x: number,
  z: number,
  aroundY: number,
  minimumY: number,
  maximumY: number,
  liquid: AquaticSpawnColumn["liquid"] = "water",
  minimumNeighborCells = 5,
): AquaticSpawnColumn | null {
  const lower = clamp(Math.floor(Math.min(minimumY, maximumY)), MIN_Y + 1, MAX_Y - 1);
  const upper = clamp(Math.ceil(Math.max(minimumY, maximumY)), MIN_Y + 1, MAX_Y - 1);
  const origin = clamp(Math.round(aroundY), lower, upper);
  let foundY: number | null = null;
  for (let offset = 0; offset <= upper - lower && foundY === null; offset += 1) {
    const below = origin - offset;
    const above = origin + offset;
    if (below >= lower && aquaticLiquidMatches(world.getBlock(x, below, z), liquid)) foundY = below;
    else if (above <= upper && aquaticLiquidMatches(world.getBlock(x, above, z), liquid)) foundY = above;
  }
  if (foundY === null) return null;
  let bottomY = foundY;
  let surfaceY = foundY;
  while (bottomY > MIN_Y + 1 && aquaticLiquidMatches(world.getBlock(x, bottomY - 1, z), liquid)) bottomY -= 1;
  while (surfaceY < MAX_Y - 1 && aquaticLiquidMatches(world.getBlock(x, surfaceY + 1, z), liquid)) surfaceY += 1;
  const sampleY = clamp(origin, bottomY, surfaceY);
  let neighborCells = 0;
  for (let dx = -1; dx <= 1; dx += 1) for (let dz = -1; dz <= 1; dz += 1) {
    if (aquaticLiquidMatches(world.getBlock(x + dx, sampleY, z + dz), liquid)) neighborCells += 1;
  }
  if (neighborCells < minimumNeighborCells) return null;
  return Object.freeze({ floorY: bottomY - 1, bottomY, surfaceY, liquid, neighborCells });
}

/** A cave floor search never falls back to the unrelated surface height. */
export function findCaveFloorY(
  world: Pick<ChunkWorld, "getBlock" | "isWalkThrough">,
  x: number,
  z: number,
  aroundY: number,
  verticalRange = 48,
) {
  const top = clamp(Math.round(aroundY + 16), MIN_Y + 1, MAX_Y - 2);
  const bottom = clamp(Math.round(aroundY - Math.max(16, verticalRange)), MIN_Y + 1, MAX_Y - 2);
  for (let y = top; y >= bottom; y -= 1) {
    const ground = world.getBlock(x, y, z);
    if (ground === undefined || !BLOCKS[ground]?.solid) continue;
    if (world.isWalkThrough(world.getBlock(x, y + 1, z)) && world.isWalkThrough(world.getBlock(x, y + 2, z))) return y;
  }
  return null;
}

/** Finds two cells of dry cave air for airborne fauna without surface fallback. */
export function findCaveAirY(
  world: Pick<ChunkWorld, "getBlock" | "isWalkThrough">,
  x: number,
  z: number,
  aroundY: number,
  verticalRange = 32,
) {
  const lower = clamp(Math.round(aroundY - verticalRange), MIN_Y + 2, MAX_Y - 3);
  const upper = clamp(Math.round(aroundY + verticalRange), MIN_Y + 2, MAX_Y - 3);
  const origin = clamp(Math.round(aroundY), lower, upper);
  for (let offset = 0; offset <= upper - lower; offset += 1) {
    for (const y of offset === 0 ? [origin] : [origin - offset, origin + offset]) {
      if (y < lower || y > upper) continue;
      const feet = world.getBlock(x, y, z);
      const head = world.getBlock(x, y + 1, z);
      if (feet === undefined || head === undefined || blockContainsWater(feet) || blockContainsWater(head)) continue;
      if (world.isWalkThrough(feet) && world.isWalkThrough(head)) return y;
    }
  }
  return null;
}

export function fishHabitatForSpawnSite(biome: BiomeId, underground: boolean, liquid: AquaticSpawnColumn["liquid"]): FishHabitat {
  if (liquid === "syrup") return "syrup-pond";
  if (underground) return "underground";
  if (biome === BiomeId.DeepOcean) return "deep-ocean";
  if (biome === BiomeId.LumenTrench) return "lumen-trench";
  if (biome === BiomeId.Ocean) return "ocean";
  if (biome === BiomeId.Glimmerwood) return "glimmer-pond";
  return "river";
}

export function fishHabitatSupportsNaturalPool(habitat: FishHabitat, pool: NaturalPopulationPool, underground = false) {
  return fishSpawnTableForHabitat(habitat).some(([kind]) => {
    const definition = MOB_DEFS[kind];
    return !definition.hostile && naturalPopulationPoolForDefinition(definition, underground) === pool;
  });
}

/** Weighted habitat choice after pool and progression-resource constraints are known. */
export function fishKindForNaturalPool(
  habitat: FishHabitat,
  pool: NaturalPopulationPool,
  underground: boolean,
  hostile: boolean,
  requiredDrop?: ItemCode,
  roll = Math.random(),
) {
  const eligible = fishSpawnTableForHabitat(habitat).filter(([kind]) => {
    const definition = MOB_DEFS[kind];
    return definition.hostile === hostile && naturalPopulationPoolForDefinition(definition, underground) === pool;
  });
  const preferred = requiredDrop === undefined ? eligible : eligible.filter(([kind]) => (
    MOB_DEFS[kind].drops?.some((drop) => drop.item === requiredDrop && drop.chance > 0)
  ));
  const choices = preferred.length ? preferred : eligible;
  const total = choices.reduce((sum, [, weight]) => sum + Math.max(0, weight), 0);
  if (total <= 0) return null;
  let cursor = clamp(Number.isFinite(roll) ? roll : 0.5, 0, 0.999999) * total;
  for (const [kind, weight] of choices) {
    cursor -= Math.max(0, weight);
    if (cursor <= 0) return kind;
  }
  return choices.at(-1)?.[0] ?? null;
}

/**
 * Aquatic structure markers carry an authored water-column height. Surface
 * pathfinding intentionally ignores water, so preserve that height instead of
 * grounding an underwater resident on the sea floor.
 */
export function structureMobSpawnY(
  world: Pick<ChunkWorld, "findWalkableY" | "getBlock">,
  kind: MobKind,
  x: number,
  z: number,
  markerY: number,
  markerTags: readonly string[] = [],
) {
  const definition = MOB_DEFS[kind];
  if (definition.movement === "aquatic") {
    const blockX = Math.round(x);
    const blockZ = Math.round(z);
    const baseY = Math.round(markerY);
    for (const offset of [0, 1, -1, 2, -2, 3, -3]) {
      const candidateY = baseY + offset;
      if (blockContainsWater(world.getBlock(blockX, candidateY, blockZ))) return candidateY;
    }
    return markerY;
  }
  // Authored airborne encounters already encode a safe interior height. A
  // surface scan would otherwise snap a Vaultwing from an observatory gallery
  // onto its roof before its first animation frame.
  if ((definition.movement === "flying" || definition.flying)
    && (kind === "vaultwing" || markerTags.includes("dungeon") || markerTags.includes("adventure-airborne"))) return markerY;
  if (markerTags.includes("dungeon")) {
    const blockX = Math.round(x);
    const blockZ = Math.round(z);
    const authoredFeetY = Math.round(markerY);
    // Dungeon room markers sit directly above their authored floor. Search
    // down only; never accept a ceiling/roof above the encounter marker.
    for (let groundY = authoredFeetY - 1; groundY >= authoredFeetY - 10; groundY -= 1) {
      const ground = world.getBlock(blockX, groundY, blockZ);
      const feet = world.getBlock(blockX, groundY + 1, blockZ);
      const head = world.getBlock(blockX, groundY + 2, blockZ);
      if (ground !== undefined && BLOCKS[ground]?.solid
        && (!feet || !BLOCKS[feet]?.solid)
        && (!head || !BLOCKS[head]?.solid)) return groundY + definition.footOffset;
    }
    return markerY;
  }
  if (markerTags.includes("authored-interior-spawn")) {
    const blockX = Math.round(x);
    const blockZ = Math.round(z);
    const authoredFeetY = Math.round(markerY);
    const ground = world.getBlock(blockX, authoredFeetY - 1, blockZ);
    const feet = world.getBlock(blockX, authoredFeetY, blockZ);
    const head = world.getBlock(blockX, authoredFeetY + 1, blockZ);
    if (ground !== undefined && BLOCKS[ground]?.solid
      && (!feet || !BLOCKS[feet]?.solid)
      && (!head || !BLOCKS[head]?.solid)) return authoredFeetY - 1 + definition.footOffset;
    return markerY;
  }
  return world.findWalkableY(Math.round(x), Math.round(z), markerY) + definition.footOffset;
}

export function mapLocationNameFromTag(tag: string) {
  if (tag.startsWith("guild-hall:") || tag.startsWith("guild-lodge:")) {
    const [, guildId] = tag.split(":");
    const guildName = GUILDS[guildId as GuildId]?.name ?? guildId.split("-").map((part) => part ? part[0].toUpperCase() + part.slice(1) : part).join(" ");
    return `${guildName} ${tag.startsWith("guild-lodge:") ? "Field Lodge" : "Hall"}`;
  }
  if (tag.startsWith("adventure-poi:") || tag.startsWith("dungeon:")) {
    const suffix = tag.slice(tag.indexOf(":") + 1);
    return suffix.split("-").map((part) => part ? part[0].toUpperCase() + part.slice(1) : part).join(" ");
  }
  return tag.split(":")[0].split("-").map((part) => part ? part[0].toUpperCase() + part.slice(1) : part).join(" ");
}

export function planHostileAirbornePursuit(input: Readonly<{
  hostile: boolean;
  aware: boolean;
  distance: number;
  chaseSpeed: number;
  reach: number;
  cooldownSeconds: number;
  dt: number;
}>) {
  const distance = Math.max(0, Number.isFinite(input.distance) ? input.distance : 0);
  if (!input.hostile || !input.aware) return { advance: 0, nextDistance: distance, attacks: false } as const;
  const attacks = distance <= Math.max(0.5, input.reach) && input.cooldownSeconds <= 0;
  const advance = attacks ? 0 : Math.min(
    Math.max(0, distance - Math.max(0.5, input.reach) * 0.72),
    Math.max(0, input.chaseSpeed) * Math.max(0, Math.min(input.dt, 0.1)),
  );
  return { advance, nextDistance: Math.max(0, distance - advance), attacks } as const;
}

export function normalizeCaptureOrbInventorySlot(slot: InventorySlot | null | undefined) {
  const copy = cloneSlot(slot ?? null);
  return copy ? migrateCaptureOrbInventorySlot(copy) : null;
}

export function normalizeLeviathanCargoStorage(value: unknown, chestModules: number): ChestState {
  const size = clamp(Math.floor(Number(chestModules) || 0), 0, 6) * 27;
  if (size <= 0) return [];
  const slots = Array.isArray(value) ? value : [];
  return Array.from({ length: size }, (_, index) => normalizeCaptureOrbInventorySlot(
    slots[index] && typeof slots[index] === "object" ? slots[index] as InventorySlot : null,
  ));
}

export function normalizeDragonCargoStorage(value: unknown, slotCount: number): ChestState {
  const size = clamp(Math.floor(Number(slotCount) || 0), 0, 36);
  if (size <= 0) return [];
  const slots = Array.isArray(value) ? value : [];
  return Array.from({ length: size }, (_, index) => normalizeCaptureOrbInventorySlot(
    slots[index] && typeof slots[index] === "object" ? slots[index] as InventorySlot : null,
  ));
}

let looseCaptureOrbSerial = 0;

export function captureOrbUnitFromInventorySlot(slot: InventorySlot | null | undefined) {
  if (!slot || (slot.item !== Item.CaptureOrb && slot.item !== Item.LegacyCaptureOrb && ITEMS[slot.item]?.useKind !== "capture-orb") || slot.count <= 0) return null;
  // Identity-bearing records are singletons. A malformed metadata stack must
  // never silently mint a different empty shell and strand the specimen.
  if (slot.count !== 1 && (typeof slot.metadata?.captureOrb === "string"
    || typeof slot.metadata?.capturedCreature === "string")) return null;
  const exact = captureOrbFromInventorySlot(slot);
  if (exact) return exact;
  // Plain crafted orbs do not carry identity metadata until first use. Mint it
  // at that boundary so two orbs split from the same stack never share an id.
  looseCaptureOrbSerial += 1;
  const empty = createEmptyCaptureOrb(`orb-loose-${Date.now().toString(36)}-${looseCaptureOrbSerial.toString(36)}-${slot.item}-${slot.count}`);
  const lens = ITEMS[slot.item]?.captureLens ?? null;
  return lens ? { ...empty, lens } : empty;
}

export function apiaryWorkerTransferFromInventorySlot(slot: InventorySlot | null | undefined, worldDay = 0): Readonly<{
  worker: ApiaryBee;
  replacement: InventorySlot | null;
}> | null {
  const legacyWorker = workerBeeFromInventorySlot(slot);
  if (legacyWorker) return Object.freeze({ worker: legacyWorker, replacement: null });
  const orb = captureOrbFromInventorySlot(slot);
  const creature = orb?.creature;
  if (!orb || !creature || creature.kind !== "honeybee" || orb.attunement?.activeEntityId) return null;
  const worker: ApiaryBee = Object.freeze({
    id: creature.entityId,
    role: "worker",
    alive: creature.health > 0,
    home: false,
    outbound: false,
    carryingNectar: 0,
    lastReturnDay: Math.max(0, Math.floor(worldDay)),
    disconnectedDay: null,
    geneticSeed: creature.geneticSeed >>> 0,
    angry: creature.hostile,
    tamed: creature.tamed,
    ownerId: creature.ownerId,
    storedOrb: {
      item: Item.CaptureOrb,
      count: 1 as const,
      captureOrb: encodeCaptureOrb(orb),
    },
  });
  return Object.freeze({
    worker,
    replacement: captureOrbInventorySlot(createEmptyCaptureOrb(orb.orbId)),
  });
}

export function apiaryPhaseForWorldTime(worldTime: number): ApiaryPhase {
  const time = ((Number(worldTime) || 0) % 1 + 1) % 1;
  if (time >= 0.235 && time < 0.69) return "day";
  if (time >= 0.69 && time < 0.805) return "dusk";
  return "night";
}

const HERD_MOB_KINDS = new Set<MobKind>([
  "ridgeback", "woolhorn", "sunstep-grazer", "thimbledeer", "frostlace-hart", "reedcrown-deer",
  "wild-horse", "rimehoof-courser", "sunscar-courser", "mirestride-courser", "starbough-courser",
  "meadow-cow", "sunbloom-longhorn", "mistmane", "taffalo", "grotto-grazer",
]);
const FLOCK_MOB_KINDS = new Set<MobKind>([
  "lanternray", "prismtail-swift", "sailfin-skimmer", "ashnose-bat", "chimewing", "cinder-kite",
]);
const CEILING_ROOST_MOB_KINDS = new Set<MobKind>(["lanternray", "ashnose-bat"]);
const MILKABLE_MOB_KINDS = new Set<MobKind>(["meadow-cow", "sunbloom-longhorn"]);

export function socialGroupModeForMob(kind: MobKind): SocialGroupMode | null {
  if (HERD_MOB_KINDS.has(kind)) return "herd";
  return MOB_DEFS[kind]?.family === "fish" || FLOCK_MOB_KINDS.has(kind) ? "shoal" : null;
}

export function feedCourserBond(state: ReedstriderBond, ownerId: string, item: ItemCode): ReedstriderBond {
  if (item !== Item.Apple && item !== Item.Wheat) return state;
  const trust = Math.min(8, state.trust + (item === Item.Apple ? 2 : 1));
  return { ...state, trust, tamed: state.tamed || trust >= 6, ownerId: state.ownerId ?? (trust >= 6 ? ownerId : null) };
}

export function isStockedApiary(state: ApiaryBlockState): state is ApiaryState {
  return state.queen !== null;
}

function cloneApiaryBlockState(value: ApiaryBlockState): ApiaryBlockState {
  if (!value || value.schema !== 1) return createEmptyApiaryBlock();
  const clone = JSON.parse(JSON.stringify(value)) as ApiaryBlockState;
  const queenOrb = clone.queen !== null && clone.queenOrb && captureOrbFromInventorySlot(clone.queenOrb)?.creature?.kind === "hive-queen"
    ? cloneSlot(clone.queenOrb)
    : null;
  const common = {
    ...clone,
    workers: Array.isArray(clone.workers) ? clone.workers.slice(0, APIARY_WORKER_CAP) : [],
    nectar: clamp(Number(clone.nectar) || 0, 0, APIARY_NECTAR_CAP),
    honey: clamp(Number(clone.honey) || 0, 0, APIARY_HONEY_CAP),
    royalJelly: clamp(Number(clone.royalJelly) || 0, 0, APIARY_JELLY_CAP),
    honeyClock: Math.max(0, Number(clone.honeyClock) || 0),
    jellyClock: Math.max(0, Number(clone.jellyClock) || 0),
    workerGrowthClock: Math.max(0, Number(clone.workerGrowthClock) || 0),
    nextWorkerSerial: Math.max(0, Math.floor(Number(clone.nextWorkerSerial) || 0)),
  };
  if (clone.queen === null) {
    return { ...common, queen: null, queenOrb: null, queenDisplayEnabled: false };
  }
  return { ...common, queen: clone.queen, queenOrb, queenDisplayEnabled: clone.queenDisplayEnabled === true };
}

export function restoreApiaryStorage(saved: Record<string, ApiaryBlockState> = {}) {
  return new Map(Object.entries(saved).map(([key, state]) => [key, cloneApiaryBlockState(state)] as const));
}

function cloneCaptureOrb(orb: CaptureOrb | null | undefined) {
  return orb ? decodeCaptureOrb(encodeCaptureOrb(orb)) : null;
}

export function restoreOrbRackStorage(saved: Record<string, OrbRackState> = {}) {
  return new Map(Object.entries(saved).map(([key, state]) => [key, createOrbRack((state?.slots ?? []).map(cloneCaptureOrb))] as const));
}

export function restoreHealingStationStorage(saved: Record<string, CreatureHealerState> = {}) {
  return new Map(Object.entries(saved).map(([key, state]) => {
    const base = createCreatureHealer((state?.slots ?? []).map(cloneCaptureOrb), state?.gelUnits ?? 0, state?.gelFuelSeconds ?? 0);
    return [key, {
      ...base,
      healClock: clamp(Number(state?.healClock) || 0, 0, CREATURE_HEAL_INTERVAL_SECONDS),
      healCycles: Math.max(0, Math.floor(Number(state?.healCycles) || 0)),
    }] as const;
  }));
}

export function apiaryHudState(state: ApiaryBlockState): ApiaryHudState {
  const dormantWorkers = Array.isArray(state.workers) ? state.workers.filter((worker) => worker.alive) : [];
  if (!isStockedApiary(state)) return {
    queen: null,
    queenPresent: false,
    queenName: "No Queen",
    workers: dormantWorkers,
    workerCount: dormantWorkers.length,
    maxWorkers: APIARY_WORKER_CAP,
    nectar: state.nectar,
    nectarStatus: dormantWorkers.length ? "Queen removed · colony safely dormant" : "Awaiting a queen",
    honey: state.honey,
    honeyMax: APIARY_HONEY_CAP,
    royalJelly: state.royalJelly,
    royalJellyMax: APIARY_JELLY_CAP,
    productionProgress: 0,
    workerGrowthProgress: 0,
    queenDisplayEnabled: false,
    queenDisplayAvailable: false,
    honeyClock: state.honeyClock,
    honeyCycleSeconds: APIARY_HONEY_CYCLE_SECONDS,
    slots: [
      null,
      state.honey > 0 ? { item: Item.HoneyJar, count: state.honey } : null,
      state.royalJelly > 0 ? { item: Item.RoyalJelly, count: state.royalJelly } : null,
      ...Array.from({ length: APIARY_WORKER_CAP }, (_, index) => dormantWorkers[index] ? captureWorkerBeeItem(dormantWorkers[index]) : null),
    ],
  };
  const status = apiaryContainerStatus(state);
  const workers = livingApiaryWorkers(state);
  const away = workers.filter((worker) => !worker.home || worker.outbound).length;
  return {
    queen: state.queen.alive ? state.queen : null,
    queenPresent: state.queen.alive,
    queenName: state.queen.tamed ? "Bonded Hive Queen" : "Resident Hive Queen",
    workers,
    workerCount: workers.length,
    maxWorkers: status.workerCapacity,
    nectar: status.nectar,
    nectarStatus: away > 0 ? `${away} foraging · nectar return pending`
      : status.nectar > 0 ? "Workers home · nectar returned" : "Workers home · awaiting daylight",
    honey: status.honey,
    honeyMax: status.honeyCapacity,
    royalJelly: status.jelly,
    royalJellyMax: status.jellyCapacity,
    productionProgress: status.honeyProgress,
    workerGrowthProgress: status.workerProgress,
    queenDisplayEnabled: state.queenDisplayEnabled,
    queenDisplayAvailable: true,
    honeyClock: state.honeyClock,
    honeyCycleSeconds: APIARY_HONEY_CYCLE_SECONDS,
    slots: [
      cloneSlot(state.queenOrb) ?? apiaryBeeCaptureSlot(state.queen),
      status.honey > 0 ? { item: Item.HoneyJar, count: status.honey } : null,
      status.jelly > 0 ? { item: Item.RoyalJelly, count: status.jelly } : null,
      ...Array.from({ length: APIARY_WORKER_CAP }, (_, index) => workers[index] ? captureWorkerBeeItem(workers[index]) : null),
    ],
  };
}

export function orbMorphLoomHudState(value: unknown): OrbMorphLoomHudState {
  const state = normalizeOrbMorphLoom(value);
  return {
    ...state,
    inputSlot: orbMorphInputSlot(state),
    outputSlot: orbMorphOutputSlot(state),
    progress: state.activeJob
      ? clamp(state.activeJob.progressSeconds / Math.max(1, state.activeJob.durationSeconds), 0, 1)
      : state.outputOrb ? 1 : 0,
  };
}

export function apiaryBeeCaptureSlot(bee: ApiaryBee): InventorySlot | null {
  const kind: MobKind = bee.role === "queen" ? "hive-queen" : "honeybee";
  const definition = MOB_DEFS[kind];
  const serializableBee = { ...bee };
  delete serializableBee.storedOrb;
  const metadata: CreatureMetadata = {
    schema: 1,
    entityId: bee.id,
    kind,
    health: definition.health,
    maxHealth: definition.health,
    ageTicks: 24_000,
    baby: false,
    temperament: bee.angry ? "Defensive" : definition.temperament,
    hostile: bee.angry,
    tamed: bee.tamed,
    ownerId: bee.ownerId,
    name: bee.role === "queen" ? "Hive Queen" : "Honeybee",
    geneticSeed: bee.geneticSeed,
    command: bee.tamed ? "follow" : "wander",
    custom: { apiaryBee: { ...serializableBee, home: false, outbound: false } },
  };
  const orb = captureIntoOrb(createEmptyCaptureOrb(`apiary-${bee.id}`), metadata, Date.now());
  return orb ? captureOrbInventorySlot(orb) : null;
}

export function orbRackHudState(state: OrbRackState): OrbRackHudState {
  const status = orbRackContainerStatus(state);
  return { slots: status.slots.map((orb) => orb ? captureOrbInventorySlot(orb) : null) };
}

export function orbRackOccupancySignature(state: OrbRackState) {
  return state.slots.map((orb) => !orb ? "empty" : orb.creature ? `filled:${orb.creature.kind}:${orb.orbId}` : `orb:${orb.orbId}`).join("|");
}

export function healingStationHudState(state: CreatureHealerState): HealingStationHudState {
  const status = healingStationContainerStatus(state);
  return {
    slots: state.slots.map((orb) => orb ? captureOrbInventorySlot(orb) : null),
    gelUnits: status.gelUnits,
    gelFuelSeconds: status.gelFuelSeconds,
    gelFuelMaxSeconds: CREATURE_HEALER_GEL_SECONDS,
    fuelActive: status.fuelActive,
    healClock: state.healClock,
    healIntervalSeconds: CREATURE_HEAL_INTERVAL_SECONDS,
    healingProgress: state.slots.map((orb) => !orb?.creature || orb.creature.health >= orb.creature.maxHealth
      ? 1 : clamp(state.healClock / CREATURE_HEAL_INTERVAL_SECONDS, 0, 1)),
  };
}

export function waygridItemHudState(state: DigitalItemVault): WaygridItemHudState {
  return {
    entries: state.stacks.map((slot) => ({
      signature: digitalStackSignature(slot),
      item: slot.item,
      name: ITEMS[slot.item]?.name ?? `Item ${slot.item}`,
      count: slot.count,
      color: ITEMS[slot.item]?.color ?? "#9ba6a8",
    })).sort((left, right) => left.name.localeCompare(right.name) || left.item - right.item),
    utilization: digitalItemUtilization(state),
    cellCounts: digitalCellCounts(state),
  };
}

export function waygridCreatureHudState(state: DigitalCreatureArchive): WaygridCreatureHudState {
  const capacity = digitalCreatureCapacity(state);
  const used = state.orbs.length;
  return {
    entries: state.orbs.flatMap((orb) => orb.creature ? [{
      orbId: orb.orbId,
      kind: orb.creature.kind,
      name: orb.creature.name ?? MOB_DEFS[orb.creature.kind as MobKind]?.name ?? orb.creature.kind,
      health: orb.creature.health,
      maxHealth: orb.creature.maxHealth,
      tamed: orb.creature.tamed,
      baby: orb.creature.baby,
      fainted: Boolean(orb.attunement?.fainted || orb.creature.health <= 0),
      attuned: Boolean(orb.attunement),
    }] : []),
    utilization: {
      used,
      capacity,
      percentage: capacity <= 0 ? 0 : Math.min(100, used / capacity * 100),
      label: `${used.toLocaleString()}/${capacity.toLocaleString()}`,
    },
    cellCounts: digitalCellCounts(state),
    healProgress: clamp(state.healClock / 60, 0, 1),
  };
}

export function clearSavedWorld() {
  if (typeof window === "undefined") return;
  try {
    const storage = new WorldStorage(window.localStorage);
    try {
      if (storage.activeWorldId) storage.deleteWorld(storage.activeWorldId);
      window.localStorage.removeItem(SAVE_KEY);
    } finally {
      storage.dispose();
    }
  } catch {
    // Storage can be unavailable in private browsing.
  }
}

export function readSettings(): GameSettings {
  const mobile = typeof window !== "undefined" && (window.matchMedia?.("(pointer: coarse)").matches ?? false);
  const fallbackDistances = normalizeViewDistances({
    renderDistance: mobile ? 6 : DEFAULT_RENDER_DISTANCE,
    simulationDistance: mobile ? 4 : DEFAULT_SIMULATION_DISTANCE,
    basicRenderDistance: mobile ? 6 : DEFAULT_BASIC_RENDER_DISTANCE,
  });
  const fallback: GameSettings = {
    volume: 0.55,
    musicVolume: 0.72,
    muted: false,
    sensitivity: 0.0022,
    fov: 72,
    weather: "clear",
    showFps: false,
    showMinimap: false,
    showBreakingTexture: true,
    showBreakProgress: false,
    showToolEffectiveness: true,
    debugTelemetry: false,
    debugTelemetryMaxMinutes: 60,
    resourceMode: "auto",
    agentVoiceMode: "spatial",
    rememberedBasicRenderDistance: mobile ? 6 : DEFAULT_BASIC_RENDER_DISTANCE,
    ...fallbackDistances,
  };
  if (typeof window === "undefined") return fallback;
  try {
    const parsed = JSON.parse(window.localStorage.getItem(SETTINGS_KEY) ?? "null") as Partial<GameSettings> | null;
    if (!parsed) return fallback;
    const savedBasicDistance = Number(parsed.rememberedBasicRenderDistance ?? parsed.basicRenderDistance ?? fallback.rememberedBasicRenderDistance);
    const distances = normalizeViewDistances({
      renderDistance: Number(parsed.renderDistance ?? fallback.renderDistance),
      simulationDistance: Number(parsed.simulationDistance ?? fallback.simulationDistance),
      basicRenderDistance: savedBasicDistance,
    });
    return {
      volume: clamp(Number(parsed.volume ?? fallback.volume), 0, 1),
      musicVolume: clamp(Number(parsed.musicVolume ?? fallback.musicVolume), 0, 1),
      muted: Boolean(parsed.muted ?? fallback.muted),
      sensitivity: clamp(Number(parsed.sensitivity ?? fallback.sensitivity), 0.0008, 0.005),
      fov: clamp(Number(parsed.fov ?? fallback.fov), 55, 100),
      weather: parsed.weather === "rain" ? "rain" : "clear",
      showFps: Boolean(parsed.showFps ?? fallback.showFps),
      showMinimap: Boolean(parsed.showMinimap ?? fallback.showMinimap),
      showBreakingTexture: Boolean(parsed.showBreakingTexture ?? fallback.showBreakingTexture),
      showBreakProgress: Boolean(parsed.showBreakProgress ?? fallback.showBreakProgress),
      showToolEffectiveness: Boolean(parsed.showToolEffectiveness ?? fallback.showToolEffectiveness),
      debugTelemetry: Boolean(parsed.debugTelemetry ?? fallback.debugTelemetry),
      debugTelemetryMaxMinutes: clamp(Math.round(Number(parsed.debugTelemetryMaxMinutes ?? fallback.debugTelemetryMaxMinutes)), 1, 180),
      resourceMode: parsed.resourceMode === "cpu" || parsed.resourceMode === "memory" ? parsed.resourceMode : "auto",
      agentVoiceMode: parsed.agentVoiceMode === "off" || parsed.agentVoiceMode === "universal" ? parsed.agentVoiceMode : "spatial",
      rememberedBasicRenderDistance: Math.max(
        distances.renderDistance,
        Math.min(MAX_BASIC_RENDER_DISTANCE, Number.isFinite(savedBasicDistance) ? Math.round(savedBasicDistance) : DEFAULT_BASIC_RENDER_DISTANCE),
      ),
      ...distances,
    };
  } catch {
    return fallback;
  }
}

function writeSettings(settings: GameSettings) {
  try {
    window.localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  } catch {
    // Private browsing may disable storage.
  }
}

function blankInventory() {
  return Array.from({ length: INVENTORY_SIZE }, () => null as InventorySlot | null);
}

export function initialInventoryForMode(mode: GameMode) {
  const inventory = blankInventory();
  if (mode === "survival") inventory[0] = { item: Item.Berry, count: 3 };
  return inventory;
}

function blankFurnace(): FurnaceState {
  return { input: null, fuel: null, output: null, progress: 0, burn: 0, burnMax: 0 };
}

function blankEquipment(): Record<EquipmentSlot, InventorySlot | null> {
  return { head: null, chest: null, legs: null, feet: null };
}

export function offhandItemKind(item: ItemCode | null | undefined): "shield" | "light" | null {
  if (item === null || item === undefined) return null;
  const definition = ITEMS[item];
  if (definition?.iconKind === "shield") return "shield";
  if (item === BlockId.Torch || item === Item.DeepgearLanternItem || item === Item.LightningBugJar) return "light";
  return null;
}

function shieldKindForItem(item: ItemCode | null | undefined): ShieldKind | null {
  if (offhandItemKind(item) !== "shield") return null;
  return ITEMS[item!]?.shieldKind ?? (/iron/iu.test(ITEMS[item!]?.name ?? "") ? "iron-shield" : "wildwood-shield");
}

function networkItemStack(slot: InventorySlot | null): ItemStackSnapshot {
  const normalized = normalizeCaptureOrbInventorySlot(slot);
  if (!normalized) return null;
  return {
    item: normalized.item,
    count: normalized.count,
    ...(normalized.durability !== undefined ? { durability: normalized.durability } : {}),
    ...(normalized.metadata ? { metadata: structuredClone(normalized.metadata) } : {}),
  };
}

function inventorySlotFromNetwork(slot: ItemStackSnapshot): InventorySlot | null {
  if (!slot || !ITEMS[slot.item] || slot.count <= 0) return null;
  const candidate = normalizeCaptureOrbInventorySlot({
    item: slot.item,
    count: slot.count,
    ...(slot.durability !== undefined ? { durability: slot.durability } : {}),
    ...(slot.metadata ? { metadata: structuredClone(slot.metadata) } : {}),
  });
  return candidate ? { ...candidate, count: Math.min(candidate.count, inventorySlotStackLimit(candidate)) } : null;
}

export function normalizeMultiplayerPlayerProgression(value: Partial<PlayerProgressionSnapshot> | null | undefined, playerId: string, worldId = "multiplayer-world"): PlayerProgressionSnapshot {
  const rawProgression = value;
  const bestiary = blankBestiary();
  if (rawProgression?.bestiary && typeof rawProgression.bestiary === "object") for (const kind of MOB_ORDER) {
    const progress = rawProgression.bestiary[kind];
    if (!progress || typeof progress !== "object") continue;
    bestiary[kind] = normalizeLivingBestiaryEntry({ ...progress,
      seen: Boolean(progress.seen),
      kills: Math.max(0, Math.trunc(Number(progress.kills) || 0)),
      captures: Math.max(0, Math.trunc(Number(progress.captures) || 0)),
      ...(progress.tames !== undefined ? { tames: Math.max(0, Math.trunc(Number(progress.tames) || 0)) } : {}),
      ...(progress.breeds !== undefined ? { breeds: Math.max(0, Math.trunc(Number(progress.breeds) || 0)) } : {}),
      ...(progress.secretUnlocked !== undefined ? { secretUnlocked: Boolean(progress.secretUnlocked) } : {}),
      ...(progress.milestones && typeof progress.milestones === "object" ? {
        milestones: Object.fromEntries(Object.entries(progress.milestones).slice(0, 64).map(([key, count]) => [key.slice(0, 96), Math.max(0, Math.trunc(Number(count) || 0))])),
      } : {}),
    });
  }
  return {
    questBook: normalizeQuestBook(rawProgression?.questBook),
    sideQuestDefinitions: Array.isArray(rawProgression?.sideQuestDefinitions)
      ? structuredClone(rawProgression.sideQuestDefinitions.slice(0, 128)) : [],
    // A progression can arrive through a legacy browser-id key or from an
    // untrusted peer. Preserve its bounded map contents, but never preserve a
    // stale/foreign player identity when rebinding it to the canonical peer.
    mapKnowledge: {
      ...normalizeMapKnowledge(rawProgression?.mapKnowledge, worldId, playerId),
      playerId,
    },
    bestiary,
    plantBestiary: normalizePlantBestiaryState(rawProgression?.plantBestiary),
    blueprints: normalizeBlueprintState(rawProgression?.blueprints),
    magicState: normalizeMagicState(rawProgression?.magicState),
    potionBuffs: Object.fromEntries(Object.entries(rawProgression?.potionBuffs ?? {}).slice(0, 128)
      .flatMap(([key, expires]) => typeof expires === "number" && Number.isFinite(expires) ? [[key.slice(0, 64), Math.max(0, expires)] as const] : [])),
    rangedLoaded: Object.fromEntries(Object.entries(rawProgression?.rangedLoaded ?? {}).slice(0, 128)
      .flatMap(([item, loaded]) => /^\d{1,6}$/u.test(item) && typeof loaded === "number" && Number.isFinite(loaded)
        ? [[item, Math.max(0, Math.min(999, Math.trunc(loaded)))] as const] : [])),
    bankAccount: rawProgression?.bankAccount?.schema === 1 && rawProgression.bankAccount.ownerId === playerId
      ? structuredClone(rawProgression.bankAccount) : createBankAccount(worldId, playerId, 0),
    stockMarket: rawProgression?.stockMarket?.schema === 1 && rawProgression.stockMarket.ownerId === playerId
      ? structuredClone(rawProgression.stockMarket) : createStockMarket(worldId, playerId, worldId, 0),
    ...(rawProgression?.respawn && Number.isFinite(rawProgression.respawn.x)
      && Number.isFinite(rawProgression.respawn.y) && Number.isFinite(rawProgression.respawn.z) ? { respawn: {
        x: clamp(Number(rawProgression.respawn.x), -30_000_000, 30_000_000),
        y: clamp(Number(rawProgression.respawn.y), MIN_Y, MAX_Y),
        z: clamp(Number(rawProgression.respawn.z), -30_000_000, 30_000_000),
      } } : {}),
  };
}

export type MultiplayerBreakDrop = { type: BlockId; x: number; y: number; z: number; item?: ItemCode };

/** Mirrors local logical-structure drops for a host resolving guest edits. */
export function multiplayerBreakDropPlan(blocks: readonly { type: BlockId; x: number; y: number; z: number }[]) {
  const drops: MultiplayerBreakDrop[] = [];
  const structures = new Set<string>();
  for (const block of blocks) {
    if (isDoorBlock(block.type)) {
      const key = `door:${block.x},${lowerDoorY(block.type, block.y)},${block.z}`;
      if (structures.has(key)) continue;
      structures.add(key);
      drops.push({ ...block, y: lowerDoorY(block.type, block.y), item: doorItem(block.type) });
      continue;
    }
    if (isBedBlock(block.type)) {
      const counterpart = bedCounterpart(block.type, block.x, block.y, block.z);
      const keys = [`${block.x},${block.y},${block.z}`, counterpart ? `${counterpart.x},${counterpart.y},${counterpart.z}` : ""].sort();
      const key = `bed:${keys.join("|")}`;
      if (structures.has(key)) continue;
      structures.add(key);
      drops.push({ ...block, item: Item.WildwoodBed });
      continue;
    }
    if (isDoubleTallGrass(block.type)) {
      const lowerY = block.type === BlockId.DoubleTallGrassUpper ? block.y - 1 : block.y;
      const key = `tall-grass:${block.x},${lowerY},${block.z}`;
      if (structures.has(key)) continue;
      structures.add(key);
      drops.push(block);
      continue;
    }
    drops.push(block);
  }
  return drops;
}

export const PLAYER_PROGRESS_CHUNK_BYTES = 120 * 1024;

function bytesToBase64(bytes: Uint8Array) {
  let binary = "";
  for (let offset = 0; offset < bytes.length; offset += 8_192) {
    binary += String.fromCharCode(...bytes.subarray(offset, Math.min(bytes.length, offset + 8_192)));
  }
  return btoa(binary);
}

function base64ToBytes(encoded: string) {
  const binary = atob(encoded);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

export function encodePlayerProgressionChunks(value: PlayerProgressionSnapshot, maxChunkBytes = PLAYER_PROGRESS_CHUNK_BYTES) {
  const bytes = new TextEncoder().encode(JSON.stringify(value));
  const chunks: string[] = [];
  const bounded = Math.max(1_024, Math.min(PLAYER_PROGRESS_CHUNK_BYTES, Math.trunc(maxChunkBytes)));
  for (let offset = 0; offset < bytes.length; offset += bounded) chunks.push(bytesToBase64(bytes.subarray(offset, offset + bounded)));
  return chunks.length ? chunks : [bytesToBase64(bytes)];
}

export function decodePlayerProgressionChunks(chunks: readonly string[], playerId: string) {
  const parts = chunks.map(base64ToBytes);
  const length = parts.reduce((sum, part) => sum + part.length, 0);
  const joined = new Uint8Array(length);
  let offset = 0;
  for (const part of parts) { joined.set(part, offset); offset += part.length; }
  const parsed = JSON.parse(new TextDecoder().decode(joined)) as Partial<PlayerProgressionSnapshot>;
  return normalizeMultiplayerPlayerProgression(parsed, playerId);
}

export function normalizeMultiplayerPlayerState(
  value: Partial<PlayerSessionSnapshot> | null | undefined,
  playerId: string,
  variant?: PlayerVariant,
): PlayerSessionSnapshot {
  const appearance = normalizeCharacterAppearance({
    sex: value?.sex ?? variant ?? value?.variant,
    race: value?.race,
    colors: value?.colors,
  });
  const inventory = blankInventory();
  for (let index = 0; index < Math.min(inventory.length, value?.inventory?.length ?? 0); index += 1) {
    inventory[index] = inventorySlotFromNetwork(value?.inventory?.[index] ?? null);
  }
  const equipment = blankEquipment();
  for (const slot of Object.keys(equipment) as EquipmentSlot[]) equipment[slot] = inventorySlotFromNetwork(value?.equipment?.[slot] ?? null);
  return {
    playerId,
    revision: Math.max(0, Math.trunc(Number(value?.revision) || 0)),
    variant: appearance.sex,
    sex: appearance.sex,
    ...(typeof value?.profileId === "string" ? { profileId: value.profileId } : {}),
    ...(typeof value?.browserId === "string" ? { browserId: value.browserId } : {}),
    race: appearance.race,
    colors: { ...appearance.colors },
    inventory: inventory.map(networkItemStack),
    cursor: networkItemStack(inventorySlotFromNetwork(value?.cursor ?? null)),
    trash: networkItemStack(inventorySlotFromNetwork(value?.trash ?? null)),
    equipment: Object.fromEntries((Object.keys(equipment) as EquipmentSlot[]).map((slot) => [slot, networkItemStack(equipment[slot])])) as PlayerSessionSnapshot["equipment"],
    offhand: networkItemStack(inventorySlotFromNetwork(value?.offhand ?? null)),
    selected: clamp(Math.trunc(Number(value?.selected) || 0), 0, 8),
    health: clamp(Number(value?.health ?? 10), 0, 10),
    hunger: clamp(Number(value?.hunger ?? 10), 0, 10),
    xp: Math.max(0, Number(value?.xp) || 0),
    level: Math.max(0, Math.trunc(Number(value?.level) || 0)),
    skills: normalizeSkillState(value?.skills),
  };
}

export function multiplayerPlayerStateSignature(state: PlayerSessionSnapshot) {
  // Hotbar selection is presentation intent carried by the 20 Hz unordered
  // pose lane. Leaving it in this reliable-state signature would still upload
  // the full pack on the next 80 ms sync tick after every wheel notch.
  return JSON.stringify({ ...state, revision: undefined, selected: undefined });
}

function itemLedger(slots: readonly ItemStackSnapshot[]) {
  const ledger = new Map<string, number>();
  for (const snapshot of slots) {
    const slot = inventorySlotFromNetwork(snapshot);
    if (!slot) continue;
    const key = JSON.stringify({ item: slot.item, durability: slot.durability ?? null, metadata: slot.metadata ?? null });
    ledger.set(key, (ledger.get(key) ?? 0) + slot.count);
  }
  return [...ledger.entries()].sort(([left], [right]) => left.localeCompare(right));
}

/** Exact item conservation gate for atomic guest pack + shared-container edits. */
export function multiplayerContainerTransactionConservesItems(
  beforePlayer: PlayerSessionSnapshot,
  beforeContainer: readonly ItemStackSnapshot[],
  afterPlayer: PlayerSessionSnapshot,
  afterContainer: readonly ItemStackSnapshot[],
) {
  const playerSlots = (state: PlayerSessionSnapshot): ItemStackSnapshot[] => [
    ...state.inventory,
    state.cursor ?? null,
    state.trash ?? null,
    ...Object.values(state.equipment),
    state.offhand ?? null,
  ];
  return JSON.stringify(itemLedger([...playerSlots(beforePlayer), ...beforeContainer]))
    === JSON.stringify(itemLedger([...playerSlots(afterPlayer), ...afterContainer]));
}

function addItemToMultiplayerState(
  state: PlayerSessionSnapshot,
  item: ItemCode,
  count: number,
  durability?: number,
  metadata?: Record<string, unknown>,
) {
  const slots = state.inventory.map(inventorySlotFromNetwork);
  let remaining = count;
  const incoming: InventorySlot = { item, count: 1, ...(durability !== undefined ? { durability } : {}), ...(metadata ? { metadata } : {}) };
  const limit = inventorySlotStackLimit(incoming);
  for (const slot of slots) {
    if (!slot || !inventorySlotsCanStack(slot, incoming) || slot.count >= limit) continue;
    const moved = Math.min(remaining, limit - slot.count);
    slot.count += moved;
    remaining -= moved;
    if (remaining <= 0) break;
  }
  for (let index = 0; remaining > 0 && index < slots.length; index += 1) {
    if (slots[index]) continue;
    const moved = Math.min(remaining, limit);
    slots[index] = normalizeCaptureOrbInventorySlot({ item, count: moved, ...(durability !== undefined ? { durability } : {}), ...(metadata ? { metadata } : {}) });
    remaining -= moved;
  }
  return {
    state: normalizeMultiplayerPlayerState({ ...state, inventory: slots.map(networkItemStack) }, state.playerId, state.variant),
    added: count - remaining,
  };
}

export function blockEditIntersectsPlayer(
  edit: Pick<BlockAction["edits"][number], "x" | "y" | "z" | "type">,
  player: Pick<PlayerPose, "x" | "y" | "z">,
  height = PLAYER_HEIGHT,
) {
  if (edit.type === BlockId.Air) return false;
  const halfWidth = PLAYER_RADIUS;
  return edit.x + 0.5 > player.x - halfWidth
    && edit.x - 0.5 < player.x + halfWidth
    && edit.z + 0.5 > player.z - halfWidth
    && edit.z - 0.5 < player.z + halfWidth
    && edit.y + 0.5 > player.y
    && edit.y - 0.5 < player.y + height;
}

const WILDWOOD_DOOR_PLACEMENT_BLOCKS = new Set<BlockId>([
  BlockId.DoorClosedLower, BlockId.DoorClosedUpper, BlockId.DoorXClosedLower, BlockId.DoorXClosedUpper,
]);
const WROUGHT_IRON_DOOR_PLACEMENT_BLOCKS = new Set<BlockId>([
  BlockId.WroughtIronDoorClosedLower, BlockId.WroughtIronDoorClosedUpper,
  BlockId.WroughtIronDoorXClosedLower, BlockId.WroughtIronDoorXClosedUpper,
]);
const BED_PLACEMENT_BLOCKS = new Set<BlockId>([
  BlockId.BedNorthFoot, BlockId.BedNorthHead, BlockId.BedSouthFoot, BlockId.BedSouthHead,
  BlockId.BedEastFoot, BlockId.BedEastHead, BlockId.BedWestFoot, BlockId.BedWestHead,
]);
const FENCE_GATE_PLACEMENT_BLOCKS = new Set<BlockId>([
  BlockId.FenceGateNorthSouthClosed, BlockId.FenceGateEastWestClosed,
]);

function itemCanCreatePlacementBlock(item: ItemCode, block: BlockId) {
  const base = ITEMS[item]?.placeBlock;
  if (base === undefined) return false;
  if (base === block) return true;
  if (base === BlockId.Torch) return isTorchBlock(block);
  if (base === BlockId.DoorClosedLower) return WILDWOOD_DOOR_PLACEMENT_BLOCKS.has(block);
  if (base === BlockId.WroughtIronDoorClosedLower) return WROUGHT_IRON_DOOR_PLACEMENT_BLOCKS.has(block);
  if (base === BlockId.BedNorthFoot) return BED_PLACEMENT_BLOCKS.has(block);
  if (base === BlockId.FenceGateNorthSouthClosed) return FENCE_GATE_PLACEMENT_BLOCKS.has(block);
  return false;
}

/** Host-authoritative inventory cost for an optimistic guest block placement. */
export function consumeMultiplayerPlacementItem(
  state: PlayerSessionSnapshot,
  consumedItem: number | undefined,
  edits: readonly BlockAction["edits"][number][],
) {
  if (consumedItem === undefined) return { valid: true, consumed: false, state };
  if (!ITEMS[consumedItem as ItemCode]) return { valid: false, consumed: false, state };
  const item = consumedItem as ItemCode;
  const placed = edits.filter((edit) => edit.type !== BlockId.Air);
  if (!placed.length || !placed.every((edit) => itemCanCreatePlacementBlock(item, edit.type as BlockId))) {
    return { valid: false, consumed: false, state };
  }
  const inventory = state.inventory.map(inventorySlotFromNetwork);
  const selected = inventory[state.selected];
  if (!selected || selected.item !== item || selected.count <= 0) return { valid: false, consumed: false, state };
  selected.count -= 1;
  if (selected.count <= 0) inventory[state.selected] = null;
  return {
    valid: true,
    consumed: true,
    state: normalizeMultiplayerPlayerState({
      ...state,
      inventory: inventory.map(networkItemStack),
      revision: state.revision + 1,
    }, state.playerId, state.variant),
  };
}

type RendererRecoveryTarget = {
  disposed: boolean;
  webglContextLost: boolean;
  lightRefreshTimer: number;
  renderer: Pick<THREE.WebGLRenderer, "resetState">;
  resize: () => void;
  events: Pick<EngineEvents, "onRendererState" | "onToast">;
};

export function markRendererContextLost(target: RendererRecoveryTarget) {
  if (target.disposed || target.webglContextLost) return false;
  target.webglContextLost = true;
  target.events.onRendererState?.(true);
  target.events.onToast("The graphics context paused. Blockwild is restoring the world instead of discarding it.");
  return true;
}

export function restoreRendererContext(target: RendererRecoveryTarget) {
  if (target.disposed) return false;
  target.webglContextLost = false;
  target.renderer.resetState();
  target.resize();
  target.lightRefreshTimer = 0;
  target.events.onRendererState?.(false);
  target.events.onToast("Graphics restored. The world is still here.");
  return true;
}

function blankBestiary(): BestiaryProgress {
  return createLivingBestiary();
}

const mixBestiaryHash = (hash: number, value: number) => Math.imul((hash ^ Math.trunc(value)) >>> 0, 16_777_619) >>> 0;
const mixBestiaryText = (hash: number, value: string) => {
  let mixed = hash;
  for (let index = 0; index < value.length; index += 1) mixed = mixBestiaryHash(mixed, value.charCodeAt(index));
  return mixed;
};

/** Allocation-free content hash used to reuse an unchanged 215-entry HUD snapshot. */
export function bestiaryProgressSignature(bestiary: BestiaryProgress) {
  let hash = 2_166_136_261;
  for (const kind of MOB_ORDER) {
    const progress = bestiary[kind];
    hash = mixBestiaryHash(hash, progress.schemaVersion ?? 1);
    hash = mixBestiaryHash(hash, progress.seen ? 1 : 0);
    hash = mixBestiaryHash(hash, progress.kills);
    hash = mixBestiaryHash(hash, progress.captures);
    hash = mixBestiaryHash(hash, progress.tames ?? 0);
    hash = mixBestiaryHash(hash, progress.breeds ?? 0);
    hash = mixBestiaryHash(hash, progress.secretUnlocked ? 1 : 0);
    const milestones = progress.milestones ?? {};
    for (const key in milestones) {
      hash = mixBestiaryText(hash, key);
      hash = mixBestiaryHash(hash, milestones[key] ?? 0);
    }
    hash = mixBestiaryHash(hash, progress.firstSeenAt ?? 0);
    hash = mixBestiaryHash(hash, progress.lastObservedAt ?? 0);
    hash = mixBestiaryHash(hash, progress.firstCapturedAt ?? 0);
    for (const [key, node] of Object.entries(progress.research ?? {})) {
      hash = mixBestiaryText(hash, key);
      hash = mixBestiaryHash(hash, node.progress);
      hash = mixBestiaryHash(hash, node.goal);
    }
    for (const [key, form] of Object.entries(progress.forms ?? {})) {
      hash = mixBestiaryText(hash, key);
      hash = mixBestiaryHash(hash, form.sightings);
    }
    for (const value of [...(progress.specimenIds ?? []), ...(progress.summonOrigins ?? []), ...(progress.guildLinks ?? [])]) hash = mixBestiaryText(hash, value);
    for (const [section, records] of Object.entries(progress.sections ?? {})) {
      hash = mixBestiaryText(hash, section);
      hash = mixBestiaryHash(hash, records.length);
    }
  }
  return hash >>> 0;
}

/** Keyboard gameplay shortcuts must never fire while a player is typing in UI. */
export function isEditableKeyboardTarget(target: EventTarget | null) {
  const element = target as { tagName?: string; isContentEditable?: boolean; getAttribute?: (name: string) => string | null } | null;
  const tag = element?.tagName?.toUpperCase();
  return tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT" || Boolean(element?.isContentEditable) || element?.getAttribute?.("role") === "textbox";
}

/** A guest always adopts the host snapshot mode; absent legacy values fail closed to survival. */
export function applyAuthoritativeNetworkMode(target: { mode: GameMode }, mode: WorldSnapshot["mode"] | undefined) {
  target.mode = mode === "builder" ? "builder" : "survival";
  return target.mode;
}

/** Drop expiry is actor-centered: any active player keeps nearby loot alive. */
export function shouldExpireWorldDrop(
  age: number,
  position: Readonly<{ x: number; y: number; z: number }>,
  activePlayers: readonly Readonly<{ x: number; y: number; z: number }>[],
  maxAge = 120,
  maxDistance = 85,
) {
  const maxDistanceSquared = maxDistance * maxDistance;
  const nearestSquared = activePlayers.reduce((nearest, player) => {
    const dx = position.x - player.x;
    const dy = position.y - (player.y + 0.8);
    const dz = position.z - player.z;
    return Math.min(nearest, dx * dx + dy * dy + dz * dz);
  }, Number.POSITIVE_INFINITY);
  return age > maxAge || nearestSquared > maxDistanceSquared;
}

